from __future__ import annotations

from typing import Any

from .base import ProviderTask
from .workers import IsolatedWorkerProvider


WORKER_CODE = "\nimport contextlib\nimport importlib.metadata as md\nimport json\nimport os\nimport sys\nimport time\nimport traceback\nfrom pathlib import Path\n\n# Keep fd=1 away from the JSONL protocol so Marker/Surya/llama.cpp logs cannot corrupt stdout.\n_protocol_fd = os.dup(sys.stdout.fileno())\nprotocol_out = os.fdopen(_protocol_fd, \"w\", buffering=1, encoding=\"utf-8\", closefd=True)\ntry:\n    os.dup2(sys.stderr.fileno(), sys.stdout.fileno())\nexcept Exception:\n    pass\nsys.stdout = sys.stderr\n\n_models = None\n_converter = None\n_converter_signature = None\n\n\ndef emit(payload):\n    protocol_out.write(json.dumps(payload, ensure_ascii=False) + \"\\n\")\n    protocol_out.flush()\n\n\ndef package_version(name):\n    try:\n        return md.version(name)\n    except Exception as e:\n        return f\"unavailable:{type(e).__name__}:{e}\"\n\n\ndef shutdown_marker_models():\n    global _models, _converter, _converter_signature\n    if _models is not None:\n        try:\n            with contextlib.redirect_stdout(sys.stderr):\n                from marker.models import shutdown_models\n                shutdown_models(_models)\n        except Exception:\n            traceback.print_exc(file=sys.stderr)\n    _models = None\n    _converter = None\n    _converter_signature = None\n\n\ndef ensure_converter(config):\n    global _models, _converter, _converter_signature\n    signature = json.dumps(config, ensure_ascii=False, sort_keys=True)\n    if _converter is not None and _converter_signature == signature:\n        return _converter, False\n\n    if _converter is not None or _models is not None:\n        shutdown_marker_models()\n\n    with contextlib.redirect_stdout(sys.stderr):\n        from marker.converters.pdf import PdfConverter\n        from marker.models import create_model_dict\n        from marker.config.parser import ConfigParser\n\n        config_parser = ConfigParser(config)\n        models = create_model_dict()\n        converter = PdfConverter(\n            config=config_parser.generate_config_dict(),\n            artifact_dict=models,\n            processor_list=config_parser.get_processors(),\n            renderer=config_parser.get_renderer(),\n            llm_service=None,\n        )\n\n    _models = models\n    _converter = converter\n    _converter_signature = signature\n    return _converter, True\n\n\ntry:\n    emit({\n        \"status\": \"READY\",\n        \"provider_kind\": \"marker_worker\",\n        \"package\": \"marker-pdf\",\n        \"package_version\": package_version(\"marker-pdf\"),\n        \"sys_executable\": sys.executable,\n        \"sys_prefix\": sys.prefix,\n    })\nexcept Exception as e:\n    emit({\n        \"status\": \"INIT_FAILED\",\n        \"error\": f\"{type(e).__name__}: {e}\",\n        \"traceback\": traceback.format_exc(),\n    })\n    raise\n\nfor raw_line in sys.stdin:\n    raw_line = raw_line.strip()\n    if not raw_line:\n        continue\n    try:\n        cmd = json.loads(raw_line)\n        op = str(cmd.get(\"op\") or \"\")\n        if op == \"ping\":\n            emit({\n                \"status\": \"PONG\",\n                \"nonce\": cmd.get(\"nonce\"),\n                \"sys_executable\": sys.executable,\n                \"sys_prefix\": sys.prefix,\n            })\n            continue\n        if op == \"close\":\n            shutdown_marker_models()\n            emit({\"status\": \"BYE\"})\n            break\n        if op != \"parse\":\n            emit({\"status\": \"BAD_COMMAND\", \"op\": op})\n            continue\n\n        started = time.perf_counter()\n        input_path = Path(str(cmd[\"input\"]))\n        raw_output_dir = Path(str(cmd[\"output_dir\"]))\n        raw_output_dir.mkdir(parents=True, exist_ok=True)\n\n        mode = str(cmd.get(\"mode\") or \"fast\")\n        output_format = str(cmd.get(\"output_format\") or \"markdown\")\n        force_ocr = bool(cmd.get(\"force_ocr\", True))\n        disable_image_extraction = bool(cmd.get(\"disable_image_extraction\", False))\n        paginate_output = bool(cmd.get(\"paginate_output\", False))\n        use_llm = bool(cmd.get(\"use_llm\", False))\n        if use_llm:\n            raise ValueError(\"Marker benchmark worker 当前禁止 use_llm=true；先比较本地开源解析能力\")\n\n        config = {\n            \"mode\": mode,\n            \"output_format\": output_format,\n            \"force_ocr\": force_ocr,\n            \"disable_image_extraction\": disable_image_extraction,\n            \"paginate_output\": paginate_output,\n            \"use_llm\": False,\n            \"disable_tqdm\": True,\n            \"pdftext_workers\": 1,\n        }\n\n        init_started = time.perf_counter()\n        converter, created_now = ensure_converter(config)\n        converter_init_seconds = time.perf_counter() - init_started if created_now else 0.0\n\n        with contextlib.redirect_stdout(sys.stderr):\n            rendered = converter(str(input_path))\n\n        if output_format == \"markdown\":\n            text = str(getattr(rendered, \"markdown\", \"\") or \"\")\n            result_path = raw_output_dir / \"result.md\"\n            result_path.write_text(text, encoding=\"utf-8\")\n        else:\n            dump = rendered.model_dump() if hasattr(rendered, \"model_dump\") else rendered\n            result_path = raw_output_dir / \"result.json\"\n            result_path.write_text(json.dumps(dump, ensure_ascii=False, indent=2, default=str), encoding=\"utf-8\")\n            text = json.dumps(dump, ensure_ascii=False, default=str)\n\n        metadata = getattr(rendered, \"metadata\", None)\n        metadata_path = raw_output_dir / \"metadata.json\"\n        metadata_path.write_text(\n            json.dumps(metadata, ensure_ascii=False, indent=2, default=str),\n            encoding=\"utf-8\",\n        )\n\n        emit({\n            \"status\": \"SUCCESS\",\n            \"result_path\": str(result_path),\n            \"raw_refs\": [str(result_path), str(metadata_path)],\n            \"elapsed_seconds\": time.perf_counter() - started,\n            \"converter_init_seconds\": converter_init_seconds,\n            \"converter_created_now\": created_now,\n            \"mode\": mode,\n            \"output_format\": output_format,\n            \"force_ocr\": force_ocr,\n            \"disable_image_extraction\": disable_image_extraction,\n            \"char_count\": len(text),\n        })\n    except Exception as e:\n        emit({\n            \"status\": \"FAILED\",\n            \"error\": f\"{type(e).__name__}: {e}\",\n            \"traceback\": traceback.format_exc(),\n        })\n"


class MarkerProvider(IsolatedWorkerProvider):
    default_python = ".venv-marker/bin/python"
    result_path_key = "result_path"
    worker_code = WORKER_CODE
    dependency_probe_code = "import importlib.metadata as md; print('marker-pdf=' + md.version('marker-pdf'))"

    def build_command(self, task: ProviderTask) -> dict[str, Any]:
        command = super().build_command(task)
        command.update(
            {
                "mode": str(self.config.get("mode") or "fast"),
                "output_format": str(self.config.get("output_format") or "markdown"),
                "force_ocr": bool(self.config.get("force_ocr", True)),
                "disable_image_extraction": bool(self.config.get("disable_image_extraction", False)),
                "paginate_output": bool(self.config.get("paginate_output", False)),
                "use_llm": bool(self.config.get("use_llm", False)),
            }
        )
        return command

